import{_ as t,o,c as r,a2 as s}from"./chunks/framework.gtmkOXzY.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/troubleshooting.md","filePath":"ms-flightsim/troubleshooting.md","lastUpdated":null}'),i={name:"ms-flightsim/troubleshooting.md"};function a(d,e,n,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Most problems come from three things: the pilot-job setting, the start order, or a missing companion resource. Check the server console first — the script says what it detected on every start.</p><table tabindex="0"><thead><tr><th>Problem</th><th>Cause and fix</th></tr></thead><tbody><tr><td>Players are told <em>&quot;Only licensed pilots can accept aviation contracts&quot;</em></td><td>The pilot job is required (<code>Config.PilotAuthorization.enabled = true</code>) and they don&#39;t have it. Give them the job with <code>/setjob</code>, or set it to <code>false</code> for open access. The console prints which mode is active</td></tr><tr><td><em>&quot;Plane certificate required&quot;</em> or <em>&quot;Helicopter certificate required&quot;</em></td><td>The player hasn&#39;t passed the licence at the Training NPC yet. This applies in open-access mode too</td></tr><tr><td><em>&quot;Requires physical … license — purchase at City Hall&quot;</em></td><td><code>Config.CityHallBridge.requirePhysicalLicense</code> is on. Set it to <code>false</code> unless you want the city-hall step</td></tr><tr><td>The aircraft dealer is empty</td><td>The dealer shows the reason, and the server console prints a <code>dealer refused</code> or <code>dealer is EMPTY</code> line. Most often the character holds specialist ratings but not the base <strong>plane</strong> or <strong>helicopter</strong> licence, or the licences belong to another character. If the console says aircraft are hidden, restore them in <code>/adminps</code> → <strong>Aircraft</strong></td></tr><tr><td>F8: <code>MS_FlightSim_MSE/bridge/client.lua:116 … global &#39;lib&#39;</code></td><td>Fixed in 4.6.0. Update <code>MS_FlightSim_MSE</code> along with MS_FlightSim</td></tr><tr><td>A job shows as locked in the tablet</td><td>Rank or rating missing. The card shows the reason; see <a href="./jobs">Jobs</a></td></tr><tr><td><em>&quot;No supported framework found&quot;</em></td><td>MS_FlightSim started before your framework. Move its ensure line to the end</td></tr><tr><td>No AI aircraft at the stands</td><td>By design they appear only when ground crew are signed on. Run <code>/aitraffic why</code> (needs the <code>msflightsim.admin</code> ace) to see the reason</td></tr><tr><td>Ground board or tower screen is black</td><td>The map or prop resource is missing, or the screen was placed with an old model. Check <code>MS_FlightSim_LSIA</code> is running and re-place it from the <strong>Screens</strong> tab</td></tr><tr><td>Sub-Company tab says &quot;not set up&quot;</td><td>Run <code>subcodiag</code> in the server console; if tables are missing, import <code>sql/migrations.sql</code></td></tr><tr><td>F10 does nothing</td><td>It only works seated in a plane or helicopter once the avionics are up. Otherwise another script uses F10: Rebind it in <strong>Settings → Key Bindings → FiveM</strong>, or use <code>/atccursor</code></td></tr><tr><td>Anyone can start any job regardless of job or rank</td><td><code>Config.Debug</code> is <code>true</code>. Set it to <code>false</code> on a live server</td></tr><tr><td>Players crash when an admin restarts something</td><td>Never restart <code>MS_FlightSim_LSIA</code> (a map) with players online</td></tr><tr><td>Your config changes disappear after an update</td><td>They were made in <code>config.lua</code>. Move them to <code>config_overrides.lua</code> (money and language settings must stay in <code>config.lua</code>; re-apply them)</td></tr><tr><td>A pay or price change in <code>config_overrides.lua</code> does nothing</td><td>Money settings are applied inside <code>config.lua</code>. Change them there, or use the <strong>Salaries</strong> dial in <code>/adminps</code></td></tr></tbody></table><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p>Open a ticket in the MikeScripts Discord with:</p><ul><li>your MS_FlightSim version and framework,</li><li>the exact message players see,</li><li>the server console output from start-up.</li></ul>',6)])])}const p=t(i,[["render",a]]);export{g as __pageData,p as default};
